def start_app():
    tasks = []
    running = True
    while running:
        print("\n--- APP QUẢN LÝ CÔNG VIỆC ASM ---")
        print("1. Thêm công việc mới")
        print("2. Hiển thị danh sách")
        print("3. Thoát chương trình")

        choice = input("Nhập lựa chọn của bạn (1-3): ")

        if choice == "1":
            new_task = input("Nhập tên công việc: ")
            tasks.append(new_task)
            print(f"Đã thêm công việc: '{new_task}' thành công!")
        elif choice == "2":
            if len(tasks) == 0:
                print("Danh sách trống.")
            else:
                print("Danh sách công việc của bạn:")
                for index, task in enumerate(tasks, start=1):
                    print(f"{index}. {task}")
        elif choice == "3":
            print("Đang thoát chương trình. Tạm biệt!")
            running = False
        else:
            print("Lựa chọn không hợp lệ, vui lòng thử lại.")

if __name__ == "__main__":
    start_app()

