def mask_api_key(prompt_text, api_key):
    """Che thông tin nhạy cảm trước khi gửi prompt cho AI"""
    if api_key in prompt_text:
        return prompt_text.replace(api_key, "[REDACTED_API_KEY]")
    return prompt_text

raw_prompt = "Hãy kiểm tra lỗi cho đoạn code kết nối với key: secret_12345"
clean_prompt = mask_api_key(raw_prompt, "secret_12345")
print(clean_prompt)

Mã nguồn mẫu cho verify_ai_generated_function:
def calculate_discount(price, discount_percent):
    """Hàm tính giá sau giảm do AI gợi ý - Cần kiểm thử biên"""
    if price < 0 or discount_percent < 0 or discount_percent > 100:
        raise ValueError("Giá trị đầu vào không hợp lệ")
    return price * (1 - discount_percent / 100)

# Kiểm thử độc lập kết quả của AI
assert calculate_discount(100, 20) == 80.0
assert calculate_discount(50, 0) == 50.0
print("Xác minh hàm do AI sinh ra thành công!")

