def find_max_element(numbers):
    """Đánh giá mã AI: Xử lý trường hợp danh sách rỗng an toàn"""
    if not numbers:
        return None

    max_val = numbers[0]
    for num in numbers:
        if num > max_val:
            max_val = num
    return max_val

