is_running = True

while is_running:
    print("\n--- DỊCH VỤ SỐ DƯ ---")
    print(f"Số dư hiện tại: {balance} VNĐ")
    print("1. Nạp tiền")
    print("2. Rút tiền")
    print("3. Thoát")

    choice = input("Lựa chọn của bạn (1-3): ")

    if choice == "1":
        amount = int(input("Nhập số tiền nạp: "))
        if amount > 0:
            balance += amount
            print("Nạp tiền thành công!")
        else:
            print("Số tiền không hợp lệ!")
    elif choice == "2":
        amount = int(input("Nhập số tiền rút: "))
        if 0 < amount <= balance:
            balance -= amount
            print("Rút tiền thành công!")
        else:
            print("Số dư không đủ hoặc số tiền không hợp lệ!")
    elif choice == "3":
        print("Cảm ơn bạn đã sử dụng dịch vụ!")
        is_running = False  # Chuyển cờ trạng thái để dừng vòng lặp tự nhiên
    else:
        print("Lựa chọn không hợp lệ, vui lòng thử lại!")

